create trigger trg_inventory_entry_created
after insert on public.inventory_entries
for each row execute function public.handle_inventory_entry()

create or replace function public.handle_inventory_waste()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  lot_remaining numeric(12,3);
  item_stock numeric(12,3);
begin
  select current_stock into item_stock
  from public.inventory_items
  where id = new.inventory_item_id
  for update;

  if item_stock is null then
    raise exception 'El ítem de inventario no existe.';
  end if;

  if item_stock < new.quantity then
    raise exception 'Stock insuficiente: hay % y se quiere registrar una merma de %.', item_stock, new.quantity;
  end if;

  if new.lot_id is not null then
    select remaining_quantity into lot_remaining
    from public.inventory_lots
    where id = new.lot_id
    for update;

    if lot_remaining is null then
      raise exception 'El lote indicado no existe.';
    end if;

    if lot_remaining < new.quantity then
      raise exception 'El lote solo tiene % disponible, no se pueden dar de baja %.', lot_remaining, new.quantity;
    end if;

    update public.inventory_lots
    set remaining_quantity = remaining_quantity - new.quantity
    where id = new.lot_id;
  end if;

  update public.inventory_items
  set current_stock = current_stock - new.quantity,
      updated_at = now()
  where id = new.inventory_item_id;

  insert into public.inventory_movements (
    inventory_item_id, lot_id, movement_type, quantity,
    reference_type, reference_id, reason, created_by
  ) values (
    new.inventory_item_id, new.lot_id, 'merma', new.quantity,
    'inventory_waste', new.id, new.reason, new.created_by
  );

  return new;
end;
$$

create trigger trg_inventory_waste_created
after insert on public.inventory_waste
for each row execute function public.handle_inventory_waste()

create or replace function public.handle_inventory_adjustment()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  item_stock numeric(12,3);
begin
  select current_stock into item_stock
  from public.inventory_items
  where id = new.inventory_item_id
  for update;

  if item_stock is null then
    raise exception 'El ítem de inventario no existe.';
  end if;

  if item_stock + new.quantity_delta < 0 then
    raise exception 'El ajuste dejaría el stock en negativo (actual: %, ajuste: %).', item_stock, new.quantity_delta;
  end if;

  update public.inventory_items
  set current_stock = current_stock + new.quantity_delta,
      updated_at = now()
  where id = new.inventory_item_id;

  insert into public.inventory_movements (
    inventory_item_id, movement_type, quantity,
    reference_type, reference_id, reason, created_by
  ) values (
    new.inventory_item_id, 'ajuste', abs(new.quantity_delta),
    'inventory_adjustment', new.id, new.reason, new.created_by
  );

  return new;
end;
$$

create trigger trg_inventory_adjustment_created
after insert on public.inventory_adjustments
for each row execute function public.handle_inventory_adjustment()

create or replace function public.consume_product_inventory(
  p_product_id uuid,
  p_quantity_sold numeric,
  p_reference_type text,
  p_reference_id uuid,
  p_created_by uuid
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  req record;
  lot record;
  total_needed numeric(12,3);
  available_total numeric(12,3);
  remaining_to_consume numeric(12,3);
  take_from_lot numeric(12,3);
begin
  if p_quantity_sold <= 0 then
    raise exception 'La cantidad vendida debe ser mayor que cero.';
  end if;

  -- PASO 1: verificar que HAY suficiente de TODOS los ingredientes
  -- antes de tocar nada (para que sea todo-o-nada).
  for req in
    select inventory_item_id, quantity
    from public.product_inventory_requirements
    where product_id = p_product_id
  loop
    total_needed := req.quantity * p_quantity_sold;

    select current_stock into available_total
    from public.inventory_items
    where id = req.inventory_item_id
    for update;

    if available_total is null then
      raise exception 'El ítem de inventario % ya no existe.', req.inventory_item_id;
    end if;

    if available_total < total_needed then
      raise exception 'Stock insuficiente para vender % unidad(es): el ítem % tiene % y se necesitan %.',
        p_quantity_sold, req.inventory_item_id, available_total, total_needed;
    end if;
  end loop;

  -- PASO 2: ya confirmado que alcanza para todo, ahora sí se
  -- descuenta cada ingrediente en orden FIFO (lote más viejo primero).
  for req in
    select inventory_item_id, quantity
    from public.product_inventory_requirements
    where product_id = p_product_id
  loop
    total_needed := req.quantity * p_quantity_sold;
    remaining_to_consume := total_needed;

    for lot in
      select id, remaining_quantity
      from public.inventory_lots
      where inventory_item_id = req.inventory_item_id
        and remaining_quantity > 0
      order by received_at asc, created_at asc
      for update
    loop
      exit when remaining_to_consume <= 0;

      take_from_lot := least(lot.remaining_quantity, remaining_to_consume);

      update public.inventory_lots
      set remaining_quantity = remaining_quantity - take_from_lot
      where id = lot.id;

      insert into public.inventory_movements (
        inventory_item_id, lot_id, movement_type, quantity,
        reference_type, reference_id, created_by
      ) values (
        req.inventory_item_id, lot.id, 'salida', take_from_lot,
        p_reference_type, p_reference_id, p_created_by
      );

      remaining_to_consume := remaining_to_consume - take_from_lot;
    end loop;

    if remaining_to_consume > 0 then
      -- No debería pasar nunca si los lotes están sincronizados con
      -- current_stock, pero se protege por si acaso quedaron
      -- desincronizados.
      raise exception 'Inconsistencia de inventario: no se encontraron lotes suficientes para el ítem %.', req.inventory_item_id;
    end if;

    update public.inventory_items
    set current_stock = current_stock - total_needed,
        updated_at = now()
    where id = req.inventory_item_id;
  end loop;
end;
$$

create or replace function public.release_expired_reservations(
  p_inventory_item_id uuid default null
)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  affected integer;
begin
  update public.inventory_reservations
  set status = 'released', released_at = now()
  where status = 'reserved'
    and expires_at < now()
    and (p_inventory_item_id is null or inventory_item_id = p_inventory_item_id);

  get diagnostics affected = row_count;
  return affected;
end;
$$

create or replace function public.create_order(
  p_customer_id uuid,
  p_items jsonb,
  p_customer_message text,
  p_idempotency_key text
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_existing_order_id uuid;
  v_order_id uuid;
  v_item jsonb;
  v_product record;
  v_quantity numeric(12,3);
  v_line_total numeric(12,2);
  v_subtotal numeric(12,2) := 0;
  v_req record;
  v_needed numeric(12,3);
  v_already_reserved numeric(12,3);
  v_available numeric(12,3);
  -- acumulador de necesidades totales por ítem de inventario, para
  -- validar y reservar todo junto, no producto por producto.
  v_item_needs jsonb := '{}'::jsonb;
  v_inv_item_id text;
  v_reserved_until timestamptz := now() + interval '30 minutes';
begin
  if p_items is null or jsonb_array_length(p_items) = 0 then
    raise exception 'El pedido debe tener al menos un producto.';
  end if;

  -- IDEMPOTENCIA: si ya existe un pedido con esta misma clave
  -- (mismo intento, ej. doble clic), devolvemos el pedido existente
  -- en vez de crear uno nuevo.
  if p_idempotency_key is not null then
    select id into v_existing_order_id
    from public.orders
    where idempotency_key = p_idempotency_key;

    if v_existing_order_id is not null then
      return v_existing_order_id;
    end if;
  end if;

  -- PASO 1: validar cada producto y calcular precios desde el
  -- servidor. Acumular cuánto inventario se necesita en total.
  for v_item in select * from jsonb_array_elements(p_items)
  loop
    select id, name, price, is_active, is_available, is_sold_out
    into v_product
    from public.products
    where id = (v_item->>'product_id')::uuid;

    if v_product.id is null then
      raise exception 'Uno de los productos del pedido ya no existe.';
    end if;

    if not v_product.is_active or not v_product.is_available or v_product.is_sold_out then
      raise exception 'El producto "%" ya no está disponible.', v_product.name;
    end if;

    v_quantity := (v_item->>'quantity')::numeric;
    if v_quantity is null or v_quantity <= 0 then
      raise exception 'La cantidad de "%" debe ser mayor que cero.', v_product.name;
    end if;

    -- Acumular necesidades de inventario de este producto (receta × cantidad)
    for v_req in
      select inventory_item_id, quantity
      from public.product_inventory_requirements
      where product_id = v_product.id
    loop
      v_needed := v_req.quantity * v_quantity;
      v_inv_item_id := v_req.inventory_item_id::text;
      v_item_needs := jsonb_set(
        v_item_needs, array[v_inv_item_id],
        to_jsonb(coalesce((v_item_needs->>v_inv_item_id)::numeric, 0) + v_needed)
      );
    end loop;
  end loop;

  -- PASO 2: liberar reservas vencidas de los ítems involucrados,
  -- y verificar que alcance el stock disponible para TODOS antes
  -- de reservar nada (todo-o-nada).
  for v_inv_item_id in select jsonb_object_keys(v_item_needs)
  loop
    perform public.release_expired_reservations(v_inv_item_id::uuid);

    select current_stock into v_available
    from public.inventory_items
    where id = v_inv_item_id::uuid
    for update;

    if v_available is null then
      raise exception 'Un ítem de inventario del pedido ya no existe.';
    end if;

    select coalesce(sum(quantity), 0) into v_already_reserved
    from public.inventory_reservations
    where inventory_item_id = v_inv_item_id::uuid
      and status = 'reserved';

    v_available := v_available - v_already_reserved;
    v_needed := (v_item_needs->>v_inv_item_id)::numeric;

    if v_available < v_needed then
      raise exception 'Stock insuficiente: solo hay % disponible (ya hay % reservado por otros pedidos) y se necesitan %.',
        v_available + v_already_reserved, v_already_reserved, v_needed;
    end if;
  end loop;

  -- PASO 3: crear el pedido y sus items (ya sabemos que alcanza).
  insert into public.orders (customer_id, status, customer_message, idempotency_key, reserved_until)
  values (p_customer_id, 'pendiente_pago', p_customer_message, p_idempotency_key, v_reserved_until)
  returning id into v_order_id;

  for v_item in select * from jsonb_array_elements(p_items)
  loop
    select id, name, price into v_product
    from public.products
    where id = (v_item->>'product_id')::uuid;

    v_quantity := (v_item->>'quantity')::numeric;
    v_line_total := v_product.price * v_quantity;
    v_subtotal := v_subtotal + v_line_total;

    insert into public.order_items (
      order_id, product_id, product_name_snapshot, unit_price_snapshot,
      quantity, line_total, personalization, message, note
    ) values (
      v_order_id, v_product.id, v_product.name, v_product.price,
      v_quantity, v_line_total,
      v_item->'personalization', v_item->>'message', v_item->>'note'
    );
  end loop;

  update public.orders
  set subtotal = v_subtotal, total = v_subtotal
  where id = v_order_id;

  -- PASO 4: reservar el inventario acumulado.
  for v_inv_item_id in select jsonb_object_keys(v_item_needs)
  loop
    insert into public.inventory_reservations (
      order_id, inventory_item_id, quantity, status, expires_at
    ) values (
      v_order_id, v_inv_item_id::uuid,
      (v_item_needs->>v_inv_item_id)::numeric,
      'reserved', v_reserved_until
    );
  end loop;

  return v_order_id;
end;
$$

create or replace function public.cancel_order(
  p_order_id uuid,
  p_reason text,
  p_cancelled_by uuid
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_status text;
begin
  if p_reason is null or trim(p_reason) = '' then
    raise exception 'El motivo de cancelación es obligatorio.';
  end if;

  select status into v_status from public.orders where id = p_order_id for update;

  if v_status is null then
    raise exception 'El pedido no existe.';
  end if;

  if v_status in ('cancelado', 'finalizado', 'rechazado') then
    raise exception 'Un pedido en estado "%" no se puede cancelar.', v_status;
  end if;

  update public.orders
  set status = 'cancelado',
      cancelled_at = now(),
      cancelled_by = p_cancelled_by,
      cancellation_reason = p_reason,
      updated_at = now()
  where id = p_order_id;

  update public.inventory_reservations
  set status = 'released', released_at = now()
  where order_id = p_order_id and status = 'reserved';
end;
$$

create or replace function public.create_order(
  p_customer_name text,
  p_customer_phone text,
  p_customer_whatsapp text,
  p_items jsonb,
  p_customer_message text,
  p_idempotency_key text
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_existing_order_id uuid;
  v_customer_id uuid;
  v_order_id uuid;
  v_item jsonb;
  v_product record;
  v_quantity numeric(12,3);
  v_line_total numeric(12,2);
  v_subtotal numeric(12,2) := 0;
  v_req record;
  v_needed numeric(12,3);
  v_already_reserved numeric(12,3);
  v_available numeric(12,3);
  v_item_needs jsonb := '{}'::jsonb;
  v_inv_item_id text;
  v_reserved_until timestamptz := now() + interval '30 minutes';
begin
  if p_items is null or jsonb_array_length(p_items) = 0 then
    raise exception 'El pedido debe tener al menos un producto.';
  end if;

  if p_customer_name is null or trim(p_customer_name) = '' then
    raise exception 'El nombre del cliente es obligatorio.';
  end if;

  if p_idempotency_key is not null then
    select id into v_existing_order_id from public.orders where idempotency_key = p_idempotency_key;
    if v_existing_order_id is not null then
      return v_existing_order_id;
    end if;
  end if;

  -- Buscar cliente por teléfono, o crear uno nuevo.
  if p_customer_phone is not null and trim(p_customer_phone) <> '' then
    select id into v_customer_id from public.customers where phone = p_customer_phone;
  end if;

  if v_customer_id is null then
    insert into public.customers (name, phone, whatsapp)
    values (p_customer_name, nullif(p_customer_phone, ''), nullif(p_customer_whatsapp, ''))
    returning id into v_customer_id;
  end if;

  for v_item in select * from jsonb_array_elements(p_items)
  loop
    select id, name, price, is_active, is_available, is_sold_out
    into v_product
    from public.products
    where id = (v_item->>'product_id')::uuid;

    if v_product.id is null then
      raise exception 'Uno de los productos del pedido ya no existe.';
    end if;

    if not v_product.is_active or not v_product.is_available or v_product.is_sold_out then
      raise exception 'El producto "%" ya no está disponible.', v_product.name;
    end if;

    v_quantity := (v_item->>'quantity')::numeric;
    if v_quantity is null or v_quantity <= 0 then
      raise exception 'La cantidad de "%" debe ser mayor que cero.', v_product.name;
    end if;

    for v_req in
      select inventory_item_id, quantity
      from public.product_inventory_requirements
      where product_id = v_product.id
    loop
      v_needed := v_req.quantity * v_quantity;
      v_inv_item_id := v_req.inventory_item_id::text;
      v_item_needs := jsonb_set(
        v_item_needs, array[v_inv_item_id],
        to_jsonb(coalesce((v_item_needs->>v_inv_item_id)::numeric, 0) + v_needed)
      );
    end loop;
  end loop;

  for v_inv_item_id in select jsonb_object_keys(v_item_needs)
  loop
    perform public.release_expired_reservations(v_inv_item_id::uuid);

    select current_stock into v_available
    from public.inventory_items where id = v_inv_item_id::uuid for update;

    if v_available is null then
      raise exception 'Un ítem de inventario del pedido ya no existe.';
    end if;

    select coalesce(sum(quantity), 0) into v_already_reserved
    from public.inventory_reservations
    where inventory_item_id = v_inv_item_id::uuid and status = 'reserved';

    v_available := v_available - v_already_reserved;
    v_needed := (v_item_needs->>v_inv_item_id)::numeric;

    if v_available < v_needed then
      raise exception 'Stock insuficiente: solo hay % disponible y se necesitan %.', v_available, v_needed;
    end if;
  end loop;

  insert into public.orders (customer_id, status, customer_message, idempotency_key, reserved_until)
  values (v_customer_id, 'pendiente_pago', p_customer_message, p_idempotency_key, v_reserved_until)
  returning id into v_order_id;

  for v_item in select * from jsonb_array_elements(p_items)
  loop
    select id, name, price into v_product from public.products where id = (v_item->>'product_id')::uuid;

    v_quantity := (v_item->>'quantity')::numeric;
    v_line_total := v_product.price * v_quantity;
    v_subtotal := v_subtotal + v_line_total;

    insert into public.order_items (
      order_id, product_id, product_name_snapshot, unit_price_snapshot,
      quantity, line_total, personalization, message, note
    ) values (
      v_order_id, v_product.id, v_product.name, v_product.price,
      v_quantity, v_line_total, v_item->'personalization', v_item->>'message', v_item->>'note'
    );
  end loop;

  update public.orders set subtotal = v_subtotal, total = v_subtotal where id = v_order_id;

  for v_inv_item_id in select jsonb_object_keys(v_item_needs)
  loop
    insert into public.inventory_reservations (order_id, inventory_item_id, quantity, status, expires_at)
    values (v_order_id, v_inv_item_id::uuid, (v_item_needs->>v_inv_item_id)::numeric, 'reserved', v_reserved_until);
  end loop;

  return v_order_id;
end;
$$

create or replace function public.create_payment(
  p_order_id uuid
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_order record;
  v_existing_payment_id uuid;
  v_payment_id uuid;
begin
  select id, status, total into v_order
  from public.orders
  where id = p_order_id
  for update;

  if v_order.id is null then
    raise exception 'El pedido no existe.';
  end if;

  if v_order.status <> 'pendiente_pago' then
    raise exception 'Este pedido ya no admite un pago nuevo (estado actual: %).', v_order.status;
  end if;

  select id into v_existing_payment_id
  from public.payments
  where order_id = p_order_id and status = 'pendiente';

  if v_existing_payment_id is not null then
    return v_existing_payment_id;
  end if;

  insert into public.payments (order_id, method, amount, status)
  values (p_order_id, 'qr', v_order.total, 'pendiente')
  returning id into v_payment_id;

  return v_payment_id;
end;
$$

create or replace function public.confirm_payment(
  p_payment_id uuid
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_confirmed_by uuid;
  v_payment record;
  v_reservation record;
  v_invalid_reservations integer;
  v_lot record;
  v_remaining_to_consume numeric(12,3);
  v_take_from_lot numeric(12,3);
begin
  v_confirmed_by := auth.uid();

  if v_confirmed_by is null then
    raise exception 'No autenticado.';
  end if;

  if not public.is_employee_or_admin() then
    raise exception 'No tienes permisos para confirmar pagos.';
  end if;

  select id, order_id, status into v_payment
  from public.payments
  where id = p_payment_id
  for update;

  if v_payment.id is null then
    raise exception 'El pago no existe.';
  end if;

  if v_payment.status <> 'pendiente' then
    raise exception 'Este pago ya fue procesado (estado actual: %). No se puede confirmar dos veces.', v_payment.status;
  end if;

  -- Bloquea TODAS las reservas de este pedido antes de decidir nada,
  -- para que nadie las libere a mitad de la confirmación.
  perform 1 from public.inventory_reservations
  where order_id = v_payment.order_id
  for update;

  -- Libera cualquier reserva vencida que aún no se haya marcado.
  update public.inventory_reservations
  set status = 'released', released_at = now()
  where order_id = v_payment.order_id
    and status = 'reserved'
    and expires_at < now();

  -- Si CUALQUIER reserva de este pedido ya no está "reserved" (venció
  -- o se liberó), el inventario detrás de este pedido ya no está
  -- garantizado. Se rechaza ANTES de tocar payments/orders.
  select count(*) into v_invalid_reservations
  from public.inventory_reservations
  where order_id = v_payment.order_id
    and status <> 'reserved';

  if v_invalid_reservations > 0 then
    raise exception 'La reserva de inventario de este pedido venció o fue liberada. No se puede confirmar el pago; cancela este pedido y crea uno nuevo para volver a reservar stock.';
  end if;

  -- Recién ahora, con el inventario garantizado, se confirma.
  update public.payments
  set status = 'confirmado', confirmed_by = v_confirmed_by, confirmed_at = now(), updated_at = now()
  where id = p_payment_id;

  update public.orders
  set status = 'confirmado', updated_at = now()
  where id = v_payment.order_id;

  for v_reservation in
    select id, inventory_item_id, quantity
    from public.inventory_reservations
    where order_id = v_payment.order_id and status = 'reserved'
  loop
    v_remaining_to_consume := v_reservation.quantity;

    for v_lot in
      select id, remaining_quantity
      from public.inventory_lots
      where inventory_item_id = v_reservation.inventory_item_id
        and remaining_quantity > 0
      order by received_at asc, created_at asc
      for update
    loop
      exit when v_remaining_to_consume <= 0;

      v_take_from_lot := least(v_lot.remaining_quantity, v_remaining_to_consume);

      update public.inventory_lots
      set remaining_quantity = remaining_quantity - v_take_from_lot
      where id = v_lot.id;

      insert into public.inventory_movements (
        inventory_item_id, lot_id, movement_type, quantity,
        reference_type, reference_id, created_by
      ) values (
        v_reservation.inventory_item_id, v_lot.id, 'salida', v_take_from_lot,
        'order', v_payment.order_id, v_confirmed_by
      );

      v_remaining_to_consume := v_remaining_to_consume - v_take_from_lot;
    end loop;

    if v_remaining_to_consume > 0 then
      raise exception 'Inconsistencia de inventario al confirmar el pago: no quedan lotes suficientes para el ítem %.', v_reservation.inventory_item_id;
    end if;

    update public.inventory_items
    set current_stock = current_stock - v_reservation.quantity, updated_at = now()
    where id = v_reservation.inventory_item_id;

    update public.inventory_reservations
    set status = 'consumed', released_at = now()
    where id = v_reservation.id;
  end loop;
end;
$$

create or replace function public.reject_payment(
  p_payment_id uuid,
  p_reason text
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_rejected_by uuid;
  v_payment record;
begin
  v_rejected_by := auth.uid();

  if v_rejected_by is null then
    raise exception 'No autenticado.';
  end if;

  if not public.is_employee_or_admin() then
    raise exception 'No tienes permisos para rechazar pagos.';
  end if;

  if p_reason is null or trim(p_reason) = '' then
    raise exception 'El motivo de rechazo es obligatorio.';
  end if;

  select id, order_id, status into v_payment
  from public.payments
  where id = p_payment_id
  for update;

  if v_payment.id is null then
    raise exception 'El pago no existe.';
  end if;

  if v_payment.status <> 'pendiente' then
    raise exception 'Este pago ya fue procesado (estado actual: %).', v_payment.status;
  end if;

  update public.payments
  set status = 'rechazado', rejection_reason = p_reason,
      rejected_by = v_rejected_by, rejected_at = now(), updated_at = now()
  where id = p_payment_id;

  update public.orders
  set status = 'rechazado', updated_at = now()
  where id = v_payment.order_id;

  update public.inventory_reservations
  set status = 'released', released_at = now()
  where order_id = v_payment.order_id and status = 'reserved';
end;
$$

create or replace function public.create_payment(
  p_order_id uuid
)
returns table (
  id uuid,
  amount numeric,
  method text,
  status text
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_order record;
  v_payment_id uuid;
begin
  select o.id, o.status, o.total into v_order
  from public.orders o
  where o.id = p_order_id
  for update;

  if v_order.id is null then
    raise exception 'El pedido no existe.';
  end if;

  if v_order.status <> 'pendiente_pago' then
    raise exception 'Este pedido ya no admite un pago nuevo (estado actual: %).', v_order.status;
  end if;

  select p.id into v_payment_id
  from public.payments p
  where p.order_id = p_order_id and p.status = 'pendiente';

  if v_payment_id is null then
    insert into public.payments (order_id, method, amount, status)
    values (p_order_id, 'qr', v_order.total, 'pendiente')
    returning payments.id into v_payment_id;
  end if;

  return query
  select p.id, p.amount, p.method, p.status
  from public.payments p
  where p.id = v_payment_id;
end;
$$

