      v_needed := v_req.quantity * v_quantity;
      v_inv_item_id := v_req.inventory_item_id::text;
      v_item_needs := jsonb_set(
        v_item_needs, array[v_inv_item_id],
        to_jsonb(coalesce((v_item_needs->>v_inv_item_id)::numeric, 0) + v_needed)
      );
    end loop;
  end loop;

  for v_inv_item_id in select jsonb_object_keys(v_item_needs)
  loop
    perform public.release_expired_reservations(v_inv_item_id::uuid);

    select current_stock into v_available
    from public.inventory_items where id = v_inv_item_id::uuid for update;

    if v_available is null then
      raise exception 'Un ítem de inventario del pedido ya no existe.';
    end if;

    select coalesce(sum(quantity), 0) into v_already_reserved
    from public.inventory_reservations
    where inventory_item_id = v_inv_item_id::uuid and status = 'reserved';

    v_available := v_available - v_already_reserved;
    v_needed := (v_item_needs->>v_inv_item_id)::numeric;

    if v_available < v_needed then
      raise exception 'Stock insuficiente: solo hay % disponible y se necesitan %.', v_available, v_needed;
    end if;
  end loop;

  insert into public.orders (customer_id, status, customer_message, idempotency_key, reserved_until)
  values (v_customer_id, 'pendiente_pago', p_customer_message, p_idempotency_key, v_reserved_until)
  returning id into v_order_id;

  for v_item in select * from jsonb_array_elements(p_items)
  loop
    select id, name, price into v_product from public.products where id = (v_item->>'product_id')::uuid;

    v_quantity := (v_item->>'quantity')::numeric;
    v_line_total := v_product.price * v_quantity;
    v_subtotal := v_subtotal + v_line_total;

    insert into public.order_items (
      order_id, product_id, product_name_snapshot, unit_price_snapshot,
      quantity, line_total, personalization, message, note
    ) values (
      v_order_id, v_product.id, v_product.name, v_product.price,
      v_quantity, v_line_total, v_item->'personalization', v_item->>'message', v_item->>'note'
    );
  end loop;

  update public.orders set subtotal = v_subtotal, total = v_subtotal where id = v_order_id;

  if p_promotion_id is not null then
    perform public.apply_order_discount(v_order_id, v_subtotal, v_customer_id, p_promotion_id, null, null, null);
  end if;

  for v_inv_item_id in select jsonb_object_keys(v_item_needs)
  loop
    insert into public.inventory_reservations (order_id, inventory_item_id, quantity, status, expires_at)
    values (v_order_id, v_inv_item_id::uuid, (v_item_needs->>v_inv_item_id)::numeric, 'reserved', v_reserved_until);
  end loop;

  return v_order_id;
end;
$$

create or replace function public.check_rate_limit(
  p_ip text,
  p_route text,
  p_max_attempts int,
  p_window_seconds int
)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  v_count int;
begin
  if p_ip is null or p_ip = '' then
    raise exception 'IP requerida para rate limiting.';
  end if;

  if p_max_attempts is null or p_max_attempts <= 0 then
    raise exception 'p_max_attempts debe ser mayor a 0.';
  end if;

  if p_window_seconds is null or p_window_seconds <= 0 then
    raise exception 'p_window_seconds debe ser mayor a 0.';
  end if;

  -- Limpieza oportunista y acotada: 1% de las llamadas borran
  -- intentos de más de 1 hora en toda la tabla, para que no crezca
  -- indefinidamente sin depender de pg_cron (que puede no estar
  -- habilitado en todos los planes de Supabase).
  if random() < 0.01 then
    delete from public.rate_limit_attempts
    where created_at < now() - interval '1 hour';
  end if;

  select count(*) into v_count
  from public.rate_limit_attempts
  where ip = p_ip
    and route = p_route
    and created_at >= now() - (p_window_seconds || ' seconds')::interval;

  if v_count >= p_max_attempts then
    return false;
  end if;

  insert into public.rate_limit_attempts (ip, route)
  values (p_ip, p_route);

  return true;
end;
$$

create or replace function public.get_audit_trail(
  p_limit int default 100,
  p_offset int default 0
)
returns setof public.audit_trail
language plpgsql
security definer
set search_path = public
as $$
begin
  if not public.is_admin() then
    raise exception 'Solo un administrador puede ver el historial de auditoría.';
  end if;

  if p_limit is null or p_limit <= 0 or p_limit > 200 then
    p_limit := 100;
  end if;

  if p_offset is null or p_offset < 0 then
    p_offset := 0;
  end if;

  return query
    select *
    from public.audit_trail
    order by created_at desc
    limit p_limit offset p_offset;
end;
$$

create or replace function public.track_order_details(
  p_customer_phone text, p_order_number bigint default null, p_order_id uuid default null
) returns jsonb
language plpgsql stable security definer set search_path = public
as $$
declare v_order public.orders%rowtype; v_summary jsonb;
begin
  select o.* into v_order from public.orders o
  join public.customers c on c.id = o.customer_id
  where (case when p_order_number is not null then o.order_number = p_order_number else o.id = p_order_id end)
    and o.deleted_at is null
    and (c.phone = trim(p_customer_phone) or c.whatsapp = trim(p_customer_phone));
  if v_order.id is null then
    raise exception 'No encontramos un pedido con esos datos.';
  end if;
  select to_jsonb(t) into v_summary from public.track_order(v_order.order_number, trim(p_customer_phone)) t;
  return v_summary || jsonb_build_object(
    'id', v_order.id, 'reserved_until', v_order.reserved_until,
    'payment_status', (select p.status from public.payments p where p.order_id = v_order.id order by p.created_at desc, p.id desc limit 1)
  );
end;
$$

