      insert into public.notifications (type, message, reference_type, reference_id)
      values ('stock_bajo', 'Stock bajo: ' || new.name || ' (' || new.current_stock || ' ' || new.unit || ')', 'inventory_item', new.id);
    end if;
  end if;

  return new;
end;
$$

