CREATE OR REPLACE FUNCTION public.check_rate_limit(p_ip text, p_route text, p_max_attempts integer, p_window_seconds integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
